SourceCode.Declaration:
/// <summary>
/// Attribute class, that indicates that a method is a posting method for a given flow.
/// </summary>
public class TFMPostMethodAttribute extends SysAttribute implements SysExtensionIAttribute
{
    TableName tableName;
}

Method.Source:
/// <summary>
///    Retrieves the name of the dataset the posting method creates or modifies.
/// </summary>
/// <returns>
///    The name of dataset.
/// </returns>
public str name()
{
    return tableName;
}
